import{_ as p,C as s,o as w,c as u,j as t,a,E as o,a8 as g}from"./chunks/framework.27XeWUA0.js";const n="/schedule-dashboard/thumbs/yt/3axY1wz2OvA-640.webp",m="/schedule-dashboard/thumbs/yt/3axY1wz2OvA-1280.webp",r="/schedule-dashboard/thumbs/yt/adfw3xJBx1o-640.webp",b="/schedule-dashboard/thumbs/yt/adfw3xJBx1o-1280.webp",i="/schedule-dashboard/thumbs/yt/Bz1HFxQA1o8-640.webp",v="/schedule-dashboard/thumbs/yt/Bz1HFxQA1o8-1280.webp",l="/schedule-dashboard/thumbs/yt/UHbODjuviAU-640.webp",f="/schedule-dashboard/thumbs/yt/UHbODjuviAU-1280.webp",h="/schedule-dashboard/thumbs/yt/f_HwzoYrZ7s-640.webp",y="/schedule-dashboard/thumbs/yt/f_HwzoYrZ7s-1280.webp",Y=JSON.parse('{"title":"AI Digest · Wed 21 Oct 2026","description":"","frontmatter":{"aside":false,"outline":false},"headers":[],"params":{"date":"2026-10-21","routine":"digest"},"relativePath":"digest/2026-10-21.md","filePath":"digest/[date].md"}'),k={name:"digest/2026-10-21.md"},_=n+" 640w, "+m+" 1280w",x=r+" 640w, "+b+" 1280w",A=i+" 640w, "+v+" 1280w",z=l+" 640w, "+f+" 1280w",I=h+" 640w, "+y+" 1280w",B={id:"ai-digest-·-wed-21-oct-2026",tabindex:"-1"};function H(O,e,C,q,M,S){const c=s("Badge"),d=s("DayFilter");return w(),u("div",null,[t("h1",B,[e[0]||(e[0]=a("AI Digest · Wed 21 Oct 2026 ",-1)),o(c,{type:"tip",text:"5"}),e[1]||(e[1]=a()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#ai-digest-·-wed-21-oct-2026","aria-label":'Permalink to "AI Digest · Wed 21 Oct 2026 <Badge type="tip" text="5" />"'},"​",-1))]),e[3]||(e[3]=t("p",{class:"sub"},"AI Engineer + Better Stack, last 24h (21 Oct 2026) · run date Wed 21 Oct 2026 · 5 videos",-1)),e[4]||(e[4]=t("div",{class:"overview"},[t("p",null,[t("strong",null,"AI Engineer"),a(" posted 5 videos (about 1.5 hours), and four of them are about finance and banking. The freshest is Oliver Kennon's SemiAnalysis talk on why the GPU operator, not the chip, sets your cost per useful token (same B200, about 50% more output). The two bank talks are the most practical: Monzo's in-house coding agent now writes over 10% of merged PRs, and Cisco's Al Chen shows how to clear bank compliance fast. Coinbase's x402 talk adds real adoption numbers to a topic you've seen 4 times, and Moshi's investor talk is mostly a pitch.")]),t("p",null,[t("strong",null,"Better Stack"),a(" posted nothing new in the last 24 hours.")])],-1)),o(d),e[5]||(e[5]=g('<div class="grid cards2"><article class="it full" id="v-3axY1wz2OvA" data-title="Same GPU, 50% More Output: Why the Operator Matters — Oliver Kennon, SemiAnalysis" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=3axY1wz2OvA" target="_blank" rel="noopener"><img src="'+n+'" srcset="'+_+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=3axY1wz2OvA" target="_blank" rel="noopener">Same GPU, 50% More Output: Why the Operator Matters — Oliver Kennon, SemiAnalysis</a></h3><div class="meta">AI Engineer · Oliver Kennon, SemiAnalysis · uploaded 21 Oct, 4:30 AM IST · 17:42</div><div class="verdict v-skim"><b>Verdict:</b> skim from 3:00 — the B200 serving comparison and the relative-cost-curve point are the substance; the futures section is niche unless you buy compute at scale.</div><div class="repeat">🔁 Repeat: &#39;inference / serving&#39; — seen 29 times before. New here: an economist&#39;s view of compute as a commodity, where the operator (not the chip) sets your cost per useful token, plus a take on compute futures.</div><div class="repeat">🔁 Repeat: &#39;token costs / AI spend&#39; — seen 5 times before. New here: &quot;cost per successfully completed task&quot; as the real metric, and why your cost position only matters relative to competitors.</div><div class="sh">Compute as a commodity</div><ul><li><strong>Intelligence is the output, GPU hours the input:</strong> In a commodity market producers line up on a cost curve; the north-star metric should be price per successfully completed task at the required quality, with price per token as today&#39;s practical proxy, not the often-quoted $/GPU-hour (<a href="https://www.youtube.com/watch?v=3axY1wz2OvA&amp;t=60s" target="_blank" rel="noopener">1:00</a>–<a href="https://www.youtube.com/watch?v=3axY1wz2OvA&amp;t=180s" target="_blank" rel="noopener">3:00</a>)</li><li><strong>Operator is the multiplier:</strong> Hardware and electricity are inputs; the software and operations the operator picks multiply them into useful output (<a href="https://www.youtube.com/watch?v=3axY1wz2OvA&amp;t=141s" target="_blank" rel="noopener">2:21</a>–<a href="https://www.youtube.com/watch?v=3axY1wz2OvA&amp;t=203s" target="_blank" rel="noopener">3:23</a>)</li></ul><div class="sh">Same chip, different results</div><ul><li><strong>B200, ~50% more output:</strong> In SemiAnalysis&#39;s public InferenceX calculator, two serving stacks on B200s with 8K input / 1K output tokens and a 100 tok/s per-user target produce about 200 vs 300 output tokens/s; at the same hourly bill, the faster stack&#39;s cost per acceptable token is proportionally lower (<a href="https://www.youtube.com/watch?v=3axY1wz2OvA&amp;t=180s" target="_blank" rel="noopener">3:00</a>–<a href="https://www.youtube.com/watch?v=3axY1wz2OvA&amp;t=285s" target="_blank" rel="noopener">4:45</a>)</li><li><strong>Security counts as &quot;useful&quot;:</strong> Their security work found monitoring access exposing another customer&#39;s logs and metrics on a very fast cluster, so the service still failed; someone must also test, load-check and roll back each serving update (<a href="https://www.youtube.com/watch?v=3axY1wz2OvA&amp;t=285s" target="_blank" rel="noopener">4:45</a>–<a href="https://www.youtube.com/watch?v=3axY1wz2OvA&amp;t=393s" target="_blank" rel="noopener">6:33</a>)</li><li><strong>ClusterMAX ratings:</strong> Version 3.0 rates a couple of hundred managed GPU clusters on provisioning, reliability, monitoring and security through hands-on testing, docs and customer feedback; ratings are relative to peers and don&#39;t carry over to bare metal (<a href="https://www.youtube.com/watch?v=3axY1wz2OvA&amp;t=393s" target="_blank" rel="noopener">6:33</a>–<a href="https://www.youtube.com/watch?v=3axY1wz2OvA&amp;t=468s" target="_blank" rel="noopener">7:48</a>)</li></ul><div class="sh">Cost, competition and futures</div><ul><li><strong>Rental price isn&#39;t production cost:</strong> Count all spend (rent or amortised hardware plus software, staff and services) and divide by output customers can use; better operations cost money too and the gain must be re-earned on every new workload (<a href="https://www.youtube.com/watch?v=3axY1wz2OvA&amp;t=468s" target="_blank" rel="noopener">7:48</a>–<a href="https://www.youtube.com/watch?v=3axY1wz2OvA&amp;t=601s" target="_blank" rel="noopener">10:01</a>)</li><li><strong>Your cost position is relative:</strong> You can cut your cost per task and still end up the pricier producer if a rival improves faster; today&#39;s GPU scarcity (he sees 2–3 years of visibility) hides these gaps, so build the cost advantage now (<a href="https://www.youtube.com/watch?v=3axY1wz2OvA&amp;t=601s" target="_blank" rel="noopener">10:01</a>–<a href="https://www.youtube.com/watch?v=3axY1wz2OvA&amp;t=761s" target="_blank" rel="noopener">12:41</a>)</li><li><strong>Grades before futures:</strong> Two &quot;B200 hour&quot; offers can include different services, so a credible compute futures market needs grades and benchmarks that track the rent you actually pay; rating operators is a building block, and a rental hedge won&#39;t fix a failed deployment (<a href="https://www.youtube.com/watch?v=3axY1wz2OvA&amp;t=761s" target="_blank" rel="noopener">12:41</a>–<a href="https://www.youtube.com/watch?v=3axY1wz2OvA&amp;t=954s" target="_blank" rel="noopener">15:54</a>)</li></ul></div></article><article class="it full" id="v-adfw3xJBx1o" data-title="A Bank Built Its Own Coding Agent. It Took Off — Felipe Felisola Caso &amp; Francesco Galletta, Monzo" data-channel="AI Engineer" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=adfw3xJBx1o" target="_blank" rel="noopener"><img src="'+r+'" srcset="'+x+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=adfw3xJBx1o" target="_blank" rel="noopener">A Bank Built Its Own Coding Agent. It Took Off — Felipe Felisola Caso &amp; Francesco Galletta, Monzo</a></h3><div class="meta">AI Engineer · Felipe Felisola Caso &amp; Francesco Galletta, Monzo · uploaded 21 Oct, 12:30 AM IST · 15:30</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — short, concrete and one of the few talks with real in-house adoption numbers from a bank.</div><div class="repeat">🔁 Repeat: &#39;coding agents in production&#39; — seen 45 times before. New here: real adoption numbers from a regulated bank (10%+ of merged PRs, 1,800+ tasks a day).</div><div class="repeat">🔁 Repeat: &#39;MCP servers&#39; — seen 29 times before. New here: an internal MCP gateway that handles auth for many agents and exposes only chosen tools.</div><div class="repeat">🔁 Repeat: &#39;sandboxes for agents&#39; — seen 12 times before. New here: the &quot;box inside a box inside a box&quot; layout with controlled egress through a proxy.</div><div class="repeat">🔁 Repeat: &#39;AI in regulated industries&#39; — seen 8 times before. New here: the agent reused for incidents, data-quality on-call and non-engineer changes.</div><div class="sh">What Agent Chip is</div><ul><li><strong>Started as a Slack emoji:</strong> In January 2026 a Slack channel went viral: react to any message with the Agent Chip emoji and it becomes a prompt. It grew into an always-on teammate that answers architecture questions, reviews code and takes Linear tickets (<a href="https://www.youtube.com/watch?v=adfw3xJBx1o&amp;t=60s" target="_blank" rel="noopener">1:00</a>–<a href="https://www.youtube.com/watch?v=adfw3xJBx1o&amp;t=180s" target="_blank" rel="noopener">3:00</a>)</li><li><strong>The numbers:</strong> Monzo has 3,000+ back-end services and ~13,000 data-warehouse models; Agent Chip now authors over 10% of all merged PRs across tech and runs more than 1,800 tasks a day, with business users starting to use it for queries (<a href="https://www.youtube.com/watch?v=adfw3xJBx1o&amp;t=0s" target="_blank" rel="noopener">0:00</a>–<a href="https://www.youtube.com/watch?v=adfw3xJBx1o&amp;t=60s" target="_blank" rel="noopener">1:00</a>) (<a href="https://www.youtube.com/watch?v=adfw3xJBx1o&amp;t=180s" target="_blank" rel="noopener">3:00</a>–<a href="https://www.youtube.com/watch?v=adfw3xJBx1o&amp;t=240s" target="_blank" rel="noopener">4:00</a>)</li></ul><div class="sh">&quot;Lots of little multipliers&quot;</div><ul><li><strong>Platform did the heavy lifting:</strong> Existing alerting, monitoring, third-party integrations, staging, queues, easy deploys and database abstractions are what made it fast to build — &quot;LLMs&quot; as lots of little multipliers (<a href="https://www.youtube.com/watch?v=adfw3xJBx1o&amp;t=240s" target="_blank" rel="noopener">4:00</a>–<a href="https://www.youtube.com/watch?v=adfw3xJBx1o&amp;t=300s" target="_blank" rel="noopener">5:00</a>)</li><li><strong>MCP gateway first:</strong> Built for local coding agents, it puts internal services and knowledge sources behind one MCP server that decides deterministically what to expose and handles auth for different agents (repeat) (<a href="https://www.youtube.com/watch?v=adfw3xJBx1o&amp;t=300s" target="_blank" rel="noopener">5:00</a>–<a href="https://www.youtube.com/watch?v=adfw3xJBx1o&amp;t=360s" target="_blank" rel="noopener">6:00</a>)</li><li><strong>Sandboxed orchestration:</strong> Remote agents run in pods in an isolated namespace; the agent image fixes which CLIs and credentials exist, and a proxy allows only chosen egress (e.g. to code repos), keeping non-determinism away from production (<a href="https://www.youtube.com/watch?v=adfw3xJBx1o&amp;t=360s" target="_blank" rel="noopener">6:00</a>–<a href="https://www.youtube.com/watch?v=adfw3xJBx1o&amp;t=540s" target="_blank" rel="noopener">9:00</a>)</li></ul><div class="sh">Agent as a building block</div><ul><li><strong>Incidents and ask channels:</strong> On a new incident it joins the channel and investigates logs, traces and code while staying high-signal; in squad-to-squad &quot;ask&quot; channels it drafts answers for a human to check (<a href="https://www.youtube.com/watch?v=adfw3xJBx1o&amp;t=600s" target="_blank" rel="noopener">10:00</a>–<a href="https://www.youtube.com/watch?v=adfw3xJBx1o&amp;t=660s" target="_blank" rel="noopener">11:00</a>)</li><li><strong>Agent Chip on Call:</strong> It triages data-quality alerts reactively, and a proactive version checks back-end changes for data breakage before the next batch run; non-specialists can get a staging-tested draft before an engineer reviews (<a href="https://www.youtube.com/watch?v=adfw3xJBx1o&amp;t=660s" target="_blank" rel="noopener">11:00</a>–<a href="https://www.youtube.com/watch?v=adfw3xJBx1o&amp;t=780s" target="_blank" rel="noopener">13:00</a>)</li><li><strong>Model-agnostic by design:</strong> The agent box can be swapped for any model, and they aim to cover back-end, app, staging and data tests end-to-end (<a href="https://www.youtube.com/watch?v=adfw3xJBx1o&amp;t=780s" target="_blank" rel="noopener">13:00</a>–<a href="https://www.youtube.com/watch?v=adfw3xJBx1o&amp;t=900s" target="_blank" rel="noopener">15:00</a>)</li></ul></div></article><article class="it full" id="v-Bz1HFxQA1o8" data-title="Shipping AI Into 5 Major Banks Without a 12-Month Compliance Wait — Al Chen, Cisco" data-channel="AI Engineer" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=Bz1HFxQA1o8" target="_blank" rel="noopener"><img src="'+i+'" srcset="'+A+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=Bz1HFxQA1o8" target="_blank" rel="noopener">Shipping AI Into 5 Major Banks Without a 12-Month Compliance Wait — Al Chen, Cisco</a></h3><div class="meta">AI Engineer · Al Chen, Cisco · uploaded 20 Oct, 2:30 PM IST · 17:42</div><div class="verdict v-worth"><b>Verdict:</b> worth watching from 4:17 — the exploit-writing agent and the judge-leak fix are practical and new.</div><div class="repeat">🔁 Repeat: &#39;AI in regulated industries&#39; — seen 8 times before. New here: the concrete on-prem compliance checklist (CVE evidence, ClickHouse disaster recovery, judge leakage).</div><div class="repeat">🔁 Repeat: &#39;LLM-as-a-judge&#39; — seen 4 times before. New here: judges&#39; written reasoning can un-redact PII even when the UI looks clean.</div><div class="repeat">🔁 Repeat: &#39;privacy&#39; — seen 4 times before. New here: a two-judge pattern where the second judge only sees redacted input.</div><div class="sh">Why banks are slow</div><ul><li><strong>Production means customer apps:</strong> He means the apps millions of bank customers use, not internal RAG bots; standard SaaS AI fails on outbound egress, so it&#39;s on-prem, air-gapped deployments, and his team aims to cut a year to a couple of weeks (<a href="https://www.youtube.com/watch?v=Bz1HFxQA1o8&amp;t=0s" target="_blank" rel="noopener">0:00</a>–<a href="https://www.youtube.com/watch?v=Bz1HFxQA1o8&amp;t=120s" target="_blank" rel="noopener">2:00</a>)</li></ul><div class="sh">Pillar 1: CVEs with evidence</div><ul><li><strong>The CVE mess:</strong> Many images, each with many CVEs, across banks on different versions, scanners and severity/SLA policies; transitive open-source CVEs can&#39;t be fixed, so they must explain why to each bank&#39;s security team (<a href="https://www.youtube.com/watch?v=Bz1HFxQA1o8&amp;t=135s" target="_blank" rel="noopener">2:15</a>–<a href="https://www.youtube.com/watch?v=Bz1HFxQA1o8&amp;t=257s" target="_blank" rel="noopener">4:17</a>)</li><li><strong>Agents write the exploit:</strong> Scanners like Sysdig, Wiz and Prisma only check version bumps. They use a skill for triage and Harbor tasks (instructions, the app&#39;s Docker images, tests) where an agent writes an exploit against the old version and a test proving the new version blocks it, run in parallel on Modal or Daytona sandboxes (<a href="https://www.youtube.com/watch?v=Bz1HFxQA1o8&amp;t=257s" target="_blank" rel="noopener">4:17</a>–<a href="https://www.youtube.com/watch?v=Bz1HFxQA1o8&amp;t=420s" target="_blank" rel="noopener">7:00</a>)</li></ul><div class="sh">Pillar 2: Backup you can prove</div><ul><li><strong>ClickHouse has no managed cross-region failover:</strong> The pattern is backup to a bucket and restore to a DR region with Altinity&#39;s clickhouse-backup, then go further by checking row counts and replica convergence, since &quot;job succeeded&quot; says nothing about stale data (<a href="https://www.youtube.com/watch?v=Bz1HFxQA1o8&amp;t=420s" target="_blank" rel="noopener">7:00</a>–<a href="https://www.youtube.com/watch?v=Bz1HFxQA1o8&amp;t=600s" target="_blank" rel="noopener">10:00</a>)</li><li><strong>DR is a data-residency decision:</strong> Replicate only trace IDs and metadata across regions and keep core trace data in its jurisdiction (<a href="https://www.youtube.com/watch?v=Bz1HFxQA1o8&amp;t=570s" target="_blank" rel="noopener">9:30</a>–<a href="https://www.youtube.com/watch?v=Bz1HFxQA1o8&amp;t=630s" target="_blank" rel="noopener">10:30</a>)</li></ul><div class="sh">Pillar 3: PII leaking through judges</div><ul><li><strong>The side door:</strong> PII and MNPI get redacted at the SDK or gateway, but a judge prompt asking it to explain its score can repeat sensitive data in persisted reasoning. Fix: always keep the score, check the reasoning for sensitive data and hide it if found, or add a second judge on redacted input — &quot;zero leakage is not free&quot;, it costs another LLM call (<a href="https://www.youtube.com/watch?v=Bz1HFxQA1o8&amp;t=630s" target="_blank" rel="noopener">10:30</a>–<a href="https://www.youtube.com/watch?v=Bz1HFxQA1o8&amp;t=780s" target="_blank" rel="noopener">13:00</a>)</li><li><strong>What really sets the timeline:</strong> Ready image-pull approvals and GPUs keep it to weeks; formal security reviews, custom LLM gateways or RBAC push it out months, mostly due to organisational issues; the theme is &quot;show your work&quot; (<a href="https://www.youtube.com/watch?v=Bz1HFxQA1o8&amp;t=780s" target="_blank" rel="noopener">13:00</a>–<a href="https://www.youtube.com/watch?v=Bz1HFxQA1o8&amp;t=900s" target="_blank" rel="noopener">15:00</a>)</li></ul></div></article><article class="it full" id="v-UHbODjuviAU" data-title="The Investor&#39;s Edge Lives in Their Head — Anekha Sokhal, Moshi" data-channel="AI Engineer" data-verdict="skip"><a class="th" href="https://www.youtube.com/watch?v=UHbODjuviAU" target="_blank" rel="noopener"><img src="'+l+'" srcset="'+z+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skip">skip</span><h3><a href="https://www.youtube.com/watch?v=UHbODjuviAU" target="_blank" rel="noopener">The Investor&#39;s Edge Lives in Their Head — Anekha Sokhal, Moshi</a></h3><div class="meta">AI Engineer · Anekha Sokhal, Moshi · uploaded 20 Oct, 1:30 PM IST · 16:29</div><div class="verdict v-skip"><b>Verdict:</b> skip — a founder pitch with one useful framing (machines for the grind, humans for the decision) and almost no technical detail.</div><div class="repeat">🔁 Repeat: &#39;human-in-the-loop review&#39; — seen 13 times before. New here: little; the &quot;AI does the grind, the human makes the decision&quot; split applied to trading.</div><div class="sh">The problem</div><ul><li><strong>More data, same attention:</strong> The world made about 175 zettabytes of data in 2025; for investors paid on synthesis, the gap between data and attention keeps widening (<a href="https://www.youtube.com/watch?v=UHbODjuviAU&amp;t=0s" target="_blank" rel="noopener">0:00</a>–<a href="https://www.youtube.com/watch?v=UHbODjuviAU&amp;t=120s" target="_blank" rel="noopener">2:00</a>)</li><li><strong>The brain is the efficient engine:</strong> About 86 billion neurons on roughly 20 W, so she argues AI should feed the human, not replace them (<a href="https://www.youtube.com/watch?v=UHbODjuviAU&amp;t=120s" target="_blank" rel="noopener">2:00</a>–<a href="https://www.youtube.com/watch?v=UHbODjuviAU&amp;t=240s" target="_blank" rel="noopener">4:00</a>)</li><li><strong>What edge means:</strong> Knowing first, knowing your blind spots (second- and third-order effects) and having conviction to size up. With everyone on the same models, skills files and MCP connectors, edge is what you can&#39;t download, and it walks out when an investor leaves (<a href="https://www.youtube.com/watch?v=UHbODjuviAU&amp;t=240s" target="_blank" rel="noopener">4:00</a>–<a href="https://www.youtube.com/watch?v=UHbODjuviAU&amp;t=360s" target="_blank" rel="noopener">6:00</a>)</li></ul><div class="sh">Why not hand it to agents</div><ul><li><strong>One-person pods have hidden costs:</strong> A weekend dashboard needs security, storage, reliability and API credits once shared, and juniors lose learning by sitting next to traders (<a href="https://www.youtube.com/watch?v=UHbODjuviAU&amp;t=360s" target="_blank" rel="noopener">6:00</a>–<a href="https://www.youtube.com/watch?v=UHbODjuviAU&amp;t=540s" target="_blank" rel="noopener">9:00</a>)</li><li><strong>Someone has to stand up:</strong> When a trade goes wrong a human must explain the decision; an agent that leaks a key just says &quot;please rotate it&quot; (<a href="https://www.youtube.com/watch?v=UHbODjuviAU&amp;t=540s" target="_blank" rel="noopener">9:00</a>–<a href="https://www.youtube.com/watch?v=UHbODjuviAU&amp;t=600s" target="_blank" rel="noopener">10:00</a>)</li></ul><div class="sh">Moshi&#39;s pitch</div><ul><li><strong>Split grind from judgment:</strong> Six deterministic agents watch markets 24/7 plus the investor&#39;s own PDFs, emails and subscriptions; she claims 2.4 billion data points read, every claim measured for hallucination and traced, and up to 35% more efficiency (<a href="https://www.youtube.com/watch?v=UHbODjuviAU&amp;t=600s" target="_blank" rel="noopener">10:00</a>–<a href="https://www.youtube.com/watch?v=UHbODjuviAU&amp;t=840s" target="_blank" rel="noopener">14:00</a>)</li></ul></div></article><article class="it full" id="v-f_HwzoYrZ7s" data-title="Why AI Agents Will Need Their Own Bank Accounts — Lincoln Murr, Coinbase" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=f_HwzoYrZ7s" target="_blank" rel="noopener"><img src="'+h+'" srcset="'+I+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=f_HwzoYrZ7s" target="_blank" rel="noopener">Why AI Agents Will Need Their Own Bank Accounts — Lincoln Murr, Coinbase</a></h3><div class="meta">AI Engineer · Lincoln Murr, head of AI product, Coinbase · uploaded 20 Oct, 12:30 PM IST · 16:58</div><div class="verdict v-skim"><b>Verdict:</b> skim from 3:13 — the x402 numbers and the trading examples are new; the self-funding-agent ending is speculation.</div><div class="repeat">🔁 Repeat: &#39;agent payments / x402&#39; — seen 4 times before (two USDC/x402 talks, Apify&#39;s two &quot;agents won&#39;t pay yet&quot; talks). New here: x402 adoption figures from Coinbase itself and the &quot;agents that grow money&quot; side.</div><div class="sh">Agents that pay</div><ul><li><strong>AgentKit was a wallet with nothing to buy:</strong> About two years ago, pre-MCP, Coinbase added a crypto wallet to a LangChain agent; it worked, but there was nothing for it to pay for (<a href="https://www.youtube.com/watch?v=f_HwzoYrZ7s&amp;t=80s" target="_blank" rel="noopener">1:20</a>–<a href="https://www.youtube.com/watch?v=f_HwzoYrZ7s&amp;t=129s" target="_blank" rel="noopener">2:09</a>)</li><li><strong>x402 on HTTP 402:</strong> The never-implemented &quot;payment required&quot; status code plus stablecoins became x402, launched around last May (repeat) (<a href="https://www.youtube.com/watch?v=f_HwzoYrZ7s&amp;t=129s" target="_blank" rel="noopener">2:09</a>–<a href="https://www.youtube.com/watch?v=f_HwzoYrZ7s&amp;t=193s" target="_blank" rel="noopener">3:13</a>)</li><li><strong>Adoption beat the goal:</strong> The goal was 25,000 agent transactions by year end; by then one happened every 17 seconds, and now it&#39;s tens of millions in volume and hundreds of millions of transactions every 30 days, with Amex, PayPal, Visa, Mastercard and Stripe involved (<a href="https://www.youtube.com/watch?v=f_HwzoYrZ7s&amp;t=193s" target="_blank" rel="noopener">3:13</a>–<a href="https://www.youtube.com/watch?v=f_HwzoYrZ7s&amp;t=264s" target="_blank" rel="noopener">4:24</a>)</li><li><strong>Micropayments vs ads:</strong> With bot traffic now above human traffic, publishers could charge agents e.g. 1/10,000th of a cent per read; AWS and Cloudflare (~40% of traffic together) have enabled x402 gating, though adoption is still low (<a href="https://www.youtube.com/watch?v=f_HwzoYrZ7s&amp;t=264s" target="_blank" rel="noopener">4:24</a>–<a href="https://www.youtube.com/watch?v=f_HwzoYrZ7s&amp;t=383s" target="_blank" rel="noopener">6:23</a>)</li></ul><div class="sh">Agents that grow money</div><ul><li><strong>Three use cases:</strong> A managed portfolio (e.g. 80% S&amp;P, 5% Bitcoin, 15% T-bills), conditional &quot;if this happens, make that trade&quot; execution, and turning ideas like &quot;invest in quantum&quot; into a strategy (<a href="https://www.youtube.com/watch?v=f_HwzoYrZ7s&amp;t=383s" target="_blank" rel="noopener">6:23</a>–<a href="https://www.youtube.com/watch?v=f_HwzoYrZ7s&amp;t=494s" target="_blank" rel="noopener">8:14</a>)</li><li><strong>A weekend short by voice:</strong> After Elon agreed with a Dario post on a weekend, he placed a short on an unnamed stock from his phone in 24/7 markets; his agent now watches weekend news for market-moving stories (<a href="https://www.youtube.com/watch?v=f_HwzoYrZ7s&amp;t=494s" target="_blank" rel="noopener">8:14</a>–<a href="https://www.youtube.com/watch?v=f_HwzoYrZ7s&amp;t=588s" target="_blank" rel="noopener">9:48</a>)</li></ul><div class="sh">Lessons</div><ul><li><strong>Trust is earned step by step:</strong> He compares it to lane assist leading to Waymo, and says they&#39;ve never seen a model blow up a user&#39;s account beyond repair (<a href="https://www.youtube.com/watch?v=f_HwzoYrZ7s&amp;t=588s" target="_blank" rel="noopener">9:48</a>–<a href="https://www.youtube.com/watch?v=f_HwzoYrZ7s&amp;t=695s" target="_blank" rel="noopener">11:35</a>)</li><li><strong>AI is the enabler:</strong> Coinbase Advisor, an SEC-registered AI financial advisor, sells free 24/7 regulated advice at scale, not &quot;AI&quot;; widgets fix the blank-chat cold start; and agents with micro-VMs let Coinbase ship paper trading as a skill instead of a brokerage feature (<a href="https://www.youtube.com/watch?v=f_HwzoYrZ7s&amp;t=695s" target="_blank" rel="noopener">11:35</a>–<a href="https://www.youtube.com/watch?v=f_HwzoYrZ7s&amp;t=861s" target="_blank" rel="noopener">14:21</a>)</li></ul></div></article></div>',1))])}const P=p(k,[["render",H]]);export{Y as __pageData,P as default};
